/* Generated pronunciation data; provenance and licenses are adjacent. */
import { gunzipSync } from 'node:zlib'
export interface WakeLexicon { characters: Record<string,string>; phrases: Record<string,string>; english: Record<string,string> }
let cached: WakeLexicon | undefined
export function getWakeLexicon(): WakeLexicon {
  return cached ??= JSON.parse(gunzipSync(Buffer.from('', 'base64')).toString('utf8')) as WakeLexicon
}
